import{_ as t,o,c as n,a2 as s}from"./chunks/framework.BEUshCVJ.js";const d=JSON.parse('{"title":"Shortcuts and the panel","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/panel.md","filePath":"troubleshooting/panel.md","lastUpdated":1792715383000}'),r={name:"troubleshooting/panel.md"};function i(a,e,l,h,c,g){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="shortcuts-and-the-panel" tabindex="-1">Shortcuts and the panel <a class="header-anchor" href="#shortcuts-and-the-panel" aria-label="Permalink to &quot;Shortcuts and the panel&quot;">​</a></h1><p>This page helps when shortcuts don&#39;t work, or the panel takes focus, disappears or shows up in screen sharing.</p><h2 id="shortcuts" tabindex="-1">Shortcuts do nothing <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts do nothing {#shortcuts}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>Another program registered the same combination first (<a href="/meetcue/troubleshooting/error-codes#mc-hk-001">MC-HK-001</a>).</li><li>The foreground window belongs to a program running as administrator.</li><li>A game or video player is in exclusive full screen.</li><li>MeetCue isn&#39;t running.</li></ol><p><strong>Check</strong></p><ol><li>Look for the MeetCue icon in the notification area of the taskbar.</li><li>Open <strong>Settings › Shortcuts</strong> and look for rows marked red.</li><li>Click on the desktop and try the shortcut again.</li></ol><p><strong>Fix</strong></p><ol><li>Change any red shortcut to a free combination.</li><li>Windows doesn&#39;t pass shortcuts from administrator windows to normal programs. Use the panel buttons while such a window is in front, or run the other program without administrator rights.</li><li>Switch the full-screen program to windowed or borderless mode.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="focus" tabindex="-1">Clicking the panel takes focus from the meeting <a class="header-anchor" href="#focus" aria-label="Permalink to &quot;Clicking the panel takes focus from the meeting {#focus}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>A text field or menu in the panel needs keyboard focus.</li><li>The window manager of a remote desktop or virtual machine ignores the &quot;don&#39;t activate&quot; style.</li></ol><p><strong>Check</strong></p><ol><li>Click a talking point, then type in the meeting chat. The text should go to the chat.</li></ol><p><strong>Fix</strong></p><ol><li>Use the shortcuts instead of the mouse during a meeting.</li><li>Turn on <strong>Settings › General › Let clicks pass through the panel</strong>. The panel then ignores the mouse completely.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="position" tabindex="-1">The panel is off screen or missing <a class="header-anchor" href="#position" aria-label="Permalink to &quot;The panel is off screen or missing {#position}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>It was on an external monitor that is no longer connected.</li><li>It is hidden; <code>Ctrl+Alt+H</code> cycles full → mini → hidden.</li></ol><p><strong>Check</strong></p><ol><li>Press <code>Ctrl+Alt+H</code> once or twice.</li></ol><p><strong>Fix</strong></p><ol><li>Right-click the tray icon and choose <strong>Reset panel position</strong>.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="screen-share" tabindex="-1">Others can see the panel when I share my screen <a class="header-anchor" href="#screen-share" aria-label="Permalink to &quot;Others can see the panel when I share my screen {#screen-share}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li><strong>Hide the panel when sharing the screen</strong> is off.</li><li>The recording method captures the display output directly. Some recorders, remote support tools and external capture devices do this.</li><li>Windows 10 earlier than version 2004 doesn&#39;t support hiding windows from capture.</li></ol><p><strong>Check</strong></p><ol><li>Open <strong>Settings › General</strong> and look at <strong>Hide the panel when sharing the screen</strong>.</li><li>Start screen sharing to yourself or a colleague, or take a screenshot with <code>Win+Shift+S</code>: the panel should be missing from the picture.</li></ol><p><strong>Fix</strong></p><ol><li>Turn the setting on.</li><li>Share a single window instead of the whole screen. The panel is never part of another app&#39;s window.</li><li>Use the mini bar or hide the panel with <code>Ctrl+Alt+H</code> when you can&#39;t rely on hiding.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p>',34)])])}const u=t(r,[["render",i]]);export{d as __pageData,u as default};
